def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Find the full-length divider.
    line_col = next((c for c in range(w)
                     if all(grid[r][c] == 2 for r in range(h))), None)
    line_row = next((r for r in range(h)
                     if all(grid[r][c] == 2 for c in range(w))), None)

    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    cells = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] not in (bg, 2)]
    if not cells:
        return out

    if line_col is not None:
        lo = min(c for r, c in cells)
        hi = max(c for r, c in cells)
        if hi < line_col:             # object left of divider
            shift = line_col - 1 - hi
            marker = lo + shift - 1
        else:                         # object right of divider
            shift = line_col + 1 - lo
            marker = hi + shift + 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r][c + shift] = grid[r][c]
        if 0 <= marker < w:
            for r in range(h):
                out[r][marker] = 8

    elif line_row is not None:
        lo = min(r for r, c in cells)
        hi = max(r for r, c in cells)
        if hi < line_row:
            shift = line_row - 1 - hi
            marker = lo + shift - 1
        else:
            shift = line_row + 1 - lo
            marker = hi + shift + 1
        for r, c in cells:
            out[r][c] = bg
        for r, c in cells:
            out[r + shift][c] = grid[r][c]
        if 0 <= marker < h:
            for c in range(w):
